onClick:
{{
  Insert_Devis.run()
    .then((resultat) => {
      // 1. Message de succès
      showAlert("Devis créé avec succès !", "success");

      // 2. On ferme la modale
      closeModal('modal_add_devis');

      // 3. On rafraîchit le tableau en arrière-plan
      Get_Liste_Devis.run();

      // 4. On redirige vers la page de détail (Vérifie le nom exact de ta page !)
      if (resultat && resultat.length > 0 && resultat[0].ID_DEVIS) {
        navigateTo('Détail Devis', { id: resultat[0].ID_DEVIS });
      } else {
        showAlert("Devis créé, mais impossible d'ouvrir le détail.", "warning");
      }
    })
    .catch((error) => {
      showAlert("Erreur lors de l'enregistrement : " + error.message, "error");
    });
}}
